CREATE TABLE IF NOT EXISTS hosted_images(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,object_key TEXT UNIQUE NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,mime TEXT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS hosted_images_owner ON hosted_images(owner_id,created_at);
CREATE TABLE IF NOT EXISTS image_limits(id TEXT PRIMARY KEY,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS image_usage(id INTEGER PRIMARY KEY CHECK(id=1),bytes INTEGER NOT NULL DEFAULT 0,paused INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO image_usage(id) VALUES(1);
